const d = $input.first().json.output || $input.first().json;
const issues = [];

// 1. Validate line items
for (const it of d.items ?? []) {
  if (it.quantity == null || it.unit_price == null || it.amount == null) {
    issues.push(`Missing value for item ${it.item_code}`);
  } else if (Math.abs(it.quantity * it.unit_price - it.amount) > 0.01) {
    issues.push(`Amount mismatch for item ${it.item_code}`);
  }
}

// 2. Validate financial totals and math
const sum = (d.items ?? []).reduce((s, i) => s + (i.amount ?? 0), 0);
if (d.subtotal != null && Math.abs(sum - d.subtotal) > 0.01) issues.push("Subtotal mismatch");
if (d.vat_percent != null && d.subtotal != null && Math.abs(d.subtotal * d.vat_percent / 100 - d.vat_amount) > 0.01) issues.push("VAT amount mismatch");
if (d.subtotal != null && d.vat_amount != null && d.total != null && Math.abs(d.subtotal + d.vat_amount - d.total) > 0.01) issues.push("Total mismatch");

// 3. Validate required general fields
for (const f of ["supplier_name", "reference_pr", "total"]) {
  if (d[f] == null) issues.push(`Missing field: ${f}`);
}

// 4. Validate delivery information
if (d.delivery_date == null && d.delivery_days_after_po == null) {
  issues.push("No delivery information");
}

// 5. Validate mandatory contract/supplier terms
if (d.supplier_tin == null || d.supplier_bin == null) {
  issues.push("Missing supplier TIN or BIN");
}

if (d.advance_payment_percentage == null) {
  issues.push("Missing advance payment terms");
}

if (d.validity_days == null) {
  issues.push("Missing quotation validity period");
}

return [{ json: { ...d, extraction_issues: issues } }];

// =====================================================================
// n8n Code node: "supplier vs company"   (Mode: Run Once for Each Item)
// Aamar Garments Ltd - supplier document rules
// Deterministic: no guessing. Anything unclear -> "Needs a person to check".
// =====================================================================

// ---------- 1. Company data ----------
const PURCHASE_REQUESTS = {
  A: { pr: "PR-2026-114", desc: "Cotton twill fabric, 280 gsm", unit: "metre", qty: 12000, max: 480.0 },
  B: { pr: "PR-2026-114", desc: "Metal zipper, 18 cm",          unit: "piece", qty: 20000, max: 38.0 },
  C: { pr: "PR-2026-114", desc: "Polyester sewing thread, cone", unit: "cone",  qty: 800,   max: 210.0 },
  D: { pr: "PR-2026-114", desc: "Poly bag, 30 x 40 cm",         unit: "piece", qty: 50000, max: 6.5 },
  E: { pr: "PR-2026-114", desc: "Carton box, 5-ply",            unit: "piece", qty: 3000,  max: 95.0 },
};

// ---------- 2. Company rules (change numbers here only) ----------
const RULES = {
  priceRejectPct: 3,      // reject if unit price > max + 3%
  maxAdvancePct: 20,      // reject if advance > 20%
  maxDeliveryDays: 45,    // reject if delivery > 45 days
  checkDeliveryFrom: 31,  // 31..45 days -> person checks
  minPayDays: 30,         // balance payment window (days after delivery)
  maxPayDays: 60,
  qtyTolerancePct: 5,     // quantity difference above this -> person checks
  minValidityDays: 30,    // validity below this -> person checks
  minPenaltyPctPerWeek: 0.5,
  vatPct: 15,
  moneyTolerance: 0.011,  // rounding tolerance for arithmetic checks
};

// ---------- 3. Read input safely ----------
const input = $input.item.json;
const q = (input.quote && (input.quote.output || input.quote)) || input.output || input;

const num = (v) => (v === null || v === undefined || v === "" || isNaN(Number(v))) ? null : Number(v);
const txt = (v) => (typeof v === "string" && v.trim() !== "") ? v.trim() : null;
const fmt = (n) => Number(n).toLocaleString("en-US", { maximumFractionDigits: 4 });
const close = (a, b) => Math.abs(a - b) <= RULES.moneyTolerance;

const rejectReasons = [];
const checkReasons = [];
const addReject = (rule, detail, evidence) =>
  rejectReasons.push(`[Reject rule ${rule}] ${detail}` + (evidence ? ` Text: "${evidence}"` : ""));
const addCheck = (rule, detail, evidence) =>
  checkReasons.push(`[Check rule ${rule}] ${detail}` + (evidence ? ` Text: "${evidence}"` : ""));

const supplierName = txt(q.supplier_name) || "Unknown Supplier";
const items = Array.isArray(q.items) ? q.items : [];

// ---------- 4. Line items: match to purchase request, price, quantity, line math ----------
let firstCode = null, firstPrice = null, firstMax = null;
let itemAmountSum = 0, itemAmountsKnown = true;
let matchedPR = null;

if (items.length === 0) {
  addCheck("-", "No line items could be read from the quotation.");
  itemAmountsKnown = false;
}

for (const it of items) {
  let code = (txt(it.item_code) || "").toUpperCase();
  let pr = PURCHASE_REQUESTS[code];
  if (!pr) { // fallback: match by description
    const d = (txt(it.description) || "").toLowerCase();
    const hit = Object.entries(PURCHASE_REQUESTS).find(([, p]) => d && d.includes(p.desc.toLowerCase()));
    if (hit) { code = hit[0]; pr = hit[1]; }
  }
  if (!pr) {
    addCheck("-", `Item '${code || it.description || "?"}' could not be matched with the purchase request.`);
    itemAmountsKnown = false;
    continue;
  }
  matchedPR = pr;
  const price = num(it.unit_price), qty = num(it.quantity), amount = num(it.amount);
  if (firstCode === null) { firstCode = code; firstPrice = price; firstMax = pr.max; }

  if (price === null) {
    addCheck("-", `Item ${code}: unit price not readable.`);
  } else {
    const pctAbove = (price - pr.max) / pr.max * 100;
    if (pctAbove > RULES.priceRejectPct + 1e-9) {
      addReject(1, `Item ${code}: unit price ${fmt(price)} is ${pctAbove.toFixed(2)}% above the maximum ${fmt(pr.max)} (limit is ${RULES.priceRejectPct}%).`);
    } else if (price > pr.max + 1e-9) {
      addCheck(1, `Item ${code}: unit price ${fmt(price)} is ${pctAbove.toFixed(2)}% above the maximum ${fmt(pr.max)} (within ${RULES.priceRejectPct}%).`);
    }
  }

  if (qty === null) {
    addCheck("-", `Item ${code}: quantity not readable.`);
  } else {
    const diffPct = Math.abs(qty - pr.qty) / pr.qty * 100;
    if (diffPct > RULES.qtyTolerancePct + 1e-9) {
      addCheck(2, `Item ${code}: quantity ${fmt(qty)} differs from requested ${fmt(pr.qty)} by ${diffPct.toFixed(1)}% (limit ${RULES.qtyTolerancePct}%).`);
    }
  }

  if (qty === null || price === null || amount === null) {
    addCheck(6, `Item ${code}: quantity, unit price or amount missing, so the line total cannot be verified.`);
    itemAmountsKnown = false;
  } else {
    if (!close(qty * price, amount)) {
      addCheck(6, `Item ${code}: ${fmt(qty)} x ${fmt(price)} = ${fmt(qty * price)}, but the quotation shows ${fmt(amount)}.`);
    }
    itemAmountSum += amount;
  }
}

// purchase request reference
const refPr = txt(q.reference_pr);
if (matchedPR && refPr && refPr.toUpperCase() !== matchedPR.pr.toUpperCase()) {
  addCheck("-", `Quotation refers to ${refPr} but the matched purchase request is ${matchedPR.pr}.`);
}

// ---------- 5. Totals, VAT ----------
const subtotal = num(q.subtotal), vatPct = num(q.vat_percent), vatAmt = num(q.vat_amount), total = num(q.total);

if (vatPct === null || vatAmt === null) {
  addCheck(5, "VAT is not shown separately at 15%.");
} else if (vatPct !== RULES.vatPct) {
  addCheck(5, `VAT is shown as ${vatPct}%, not ${RULES.vatPct}%.`);
}

if (subtotal === null) {
  addCheck(6, "Subtotal is missing, so totals cannot be verified.");
} else {
  if (itemAmountsKnown && items.length > 0 && !close(itemAmountSum, subtotal)) {
    addCheck(6, `Sum of line amounts ${fmt(itemAmountSum)} does not match subtotal ${fmt(subtotal)}.`);
  }
  if (vatAmt !== null && !close(subtotal * RULES.vatPct / 100, vatAmt)) {
    addCheck(6, `15% of subtotal ${fmt(subtotal)} is ${fmt(subtotal * 0.15)}, but VAT shown is ${fmt(vatAmt)}.`);
  }
  if (vatAmt !== null && total !== null && !close(subtotal + vatAmt, total)) {
    addCheck(6, `Subtotal + VAT = ${fmt(subtotal + vatAmt)}, but total shown is ${fmt(total)}.`);
  }
}

// ---------- 6. Payment terms ----------
const payText = txt(q.payment_terms_text);
const payLower = (payText || "").toLowerCase();

let advance = num(q.advance_payment_percentage);
if (advance === null && /\b(no|nil|without)\b[^.]*\badvance/.test(payLower)) advance = 0;
if (advance === null) {
  addCheck(3, "Advance payment is not stated.", payText);
} else if (advance > RULES.maxAdvancePct) {
  addReject(2, `Advance payment ${advance}% is above the ${RULES.maxAdvancePct}% limit.`, payText);
}

const rangeMatch = /(\d+)\s*(?:to|-|–)\s*(\d+)\s*days/i.test(payText || "");
const vague = /as\s+(?:mutually\s+)?agreed|negotiable|to be agreed|subject to/i.test(payText || "");
let balanceDays = num(q.balance_payment_days);
if (balanceDays === null && payText) {
  const all = [...payText.matchAll(/(?:within|in)\s*(\d+)\s*days/gi)];
  if (all.length) balanceDays = Number(all[all.length - 1][1]);
}
if (rangeMatch || vague) {
  addCheck(3, "Payment terms are unclear (a range or 'as agreed' is given instead of a fixed period).", payText);
} else if (balanceDays === null) {
  addCheck(3, "Payment days after delivery are not stated.", payText);
} else if (balanceDays < RULES.minPayDays || balanceDays > RULES.maxPayDays) {
  addCheck(3, `Payment ${balanceDays} days after delivery is outside ${RULES.minPayDays} to ${RULES.maxPayDays} days.`, payText);
}

// ---------- 7. Delivery ----------
const delText = txt(q.delivery_text);
let delDays = num(q.delivery_days_after_po);
if (delDays === null && delText) {
  const w = delText.match(/(\d+(?:\.\d+)?)\s*weeks?/i);
  const d = delText.match(/(\d+(?:\.\d+)?)\s*days?/i);
  if (d) delDays = Number(d[1]);
  else if (w) delDays = Number(w[1]) * 7;
}
if (delDays === null) {
  addCheck("-", "Delivery time after the purchase order is not clearly stated.", delText);
} else if (delDays > RULES.maxDeliveryDays) {
  addReject(5, `Delivery in ${delDays} days is later than ${RULES.maxDeliveryDays} days after the PO.`, delText);
} else if (delDays >= RULES.checkDeliveryFrom) {
  addCheck(4, `Delivery in ${delDays} days is in the ${RULES.checkDeliveryFrom} to ${RULES.maxDeliveryDays} day range.`, delText);
}

// ---------- 8. Late-delivery penalty ----------
const penText = txt(q.late_delivery_penalty_text);
let penPct = num(q.late_delivery_penalty_percent_per_week);
const penPresent = (penText !== null || penPct !== null) && q.late_delivery_penalty_clause_present !== false;
if (!penPresent) {
  addReject(3, "The contract has no late-delivery penalty clause.");
} else {
  if (penPct === null && penText) {
    const m = penText.match(/(\d+(?:\.\d+)?)\s*%/);
    if (m) penPct = Number(m[1]);
  }
  if (penPct === null) {
    addCheck("-", "Late-delivery penalty percentage could not be read.", penText);
  } else if (penText && !/week/i.test(penText)) {
    addCheck("-", "Late-delivery penalty is not stated per week.", penText);
  } else if (penPct < RULES.minPenaltyPctPerWeek) {
    addCheck("-", `Late-delivery penalty ${penPct}% per week is below the required ${RULES.minPenaltyPctPerWeek}%.`, penText);
  }
}

// ---------- 9. TIN / BIN ----------
const tin = txt(q.supplier_tin), bin = txt(q.supplier_bin);
if (!tin || !bin) {
  addReject(4, `Supplier ${[!tin ? "TIN" : null, !bin ? "BIN" : null].filter(Boolean).join(" and ")} is missing.`);
}

// ---------- 10. Validity ----------
const validity = num(q.validity_days);
if (validity === null) {
  addCheck(7, "Quotation validity period is not stated.");
} else if (validity < RULES.minValidityDays) {
  addCheck(7, `Quotation is valid for ${validity} days, less than ${RULES.minValidityDays}.`);
}

// ---------- 11. Final decision ----------
let status = "Approve";
if (rejectReasons.length > 0) status = "Reject";
else if (checkReasons.length > 0) status = "Needs a person to check";

const reasons = [...rejectReasons, ...checkReasons];
if (reasons.length === 0) reasons.push("None of the reject or check rules applies.");

return {
  json: {
    quotation_no: txt(q.quotation_no),
    supplier_name: supplierName,
    item: firstCode,
    unit_price: firstPrice,
    max_allowed_price: firstMax,
    status,
    reasons,
    reject_reasons: rejectReasons,
    check_reasons: checkReasons,
  },
};
